#[rustfmt::skip]
const FLIP_SQ: [usize; 25] = [
    20, 21, 22, 23, 24,
    15, 16, 17, 18, 19,
    10, 11, 12, 13, 14,
     5,  6,  7,  8,  9,
     0,  1,  2,  3,  4,
];

const PIECE_TYPES: [PieceType; 6] = [
    PieceType::Pawn,
    PieceType::Knight,
    PieceType::Bishop,
    PieceType::Rook,
    PieceType::Queen,
    PieceType::King,
];

#[derive(Clone, Copy, Debug)]
enum AccKind {
    Computed,
    Null,
    Quiet,
    Capture,
}

#[derive(Clone, Copy, Debug)]
#[repr(C, align(32))]
struct AccEntry {
    w: [i16; HIDDEN],
    b: [i16; HIDDEN],
    rem1: (u16, u16),
    rem2: (u16, u16),
    add: (u16, u16),
    kind: AccKind,
}

impl AccEntry {
    const ZERO: Self = Self {
        w: [0; HIDDEN],
        b: [0; HIDDEN],
        rem1: (0, 0),
        rem2: (0, 0),
        add: (0, 0),
        kind: AccKind::Null,
    };
}

#[inline]
const fn feat_pair(piece: Piece, sq: Square) -> (u16, u16) {
    let is_white = matches!(piece.color, Color::White);
    let base_w = if is_white { 0 } else { 150 };
    let base_b = if is_white { 150 } else { 0 };
    let pt_off = piece.piece_type.index() * 25;
    let sq_i = sq.index();
    #[allow(clippy::cast_possible_truncation)]
    (
        (base_w + pt_off + sq_i) as u16,
        (base_b + pt_off + FLIP_SQ[sq_i]) as u16,
    )
}

#[inline]
fn apply_quiet(
    prev: &[i16; HIDDEN],
    cur: &mut [i16; HIDDEN],
    rem: &[i16; HIDDEN],
    add: &[i16; HIDDEN],
) {
    for ((dst, &p), (&r, &a)) in cur
        .iter_mut()
        .zip(prev.iter())
        .zip(rem.iter().zip(add.iter()))
    {
        *dst = p - r + a;
    }
}

#[inline]
fn apply_capture(
    prev: &[i16; HIDDEN],
    cur: &mut [i16; HIDDEN],
    rem1: &[i16; HIDDEN],
    rem2: &[i16; HIDDEN],
    add: &[i16; HIDDEN],
) {
    for (((dst, &p), &r1), (&r2, &a)) in cur
        .iter_mut()
        .zip(prev.iter())
        .zip(rem1.iter())
        .zip(rem2.iter().zip(add.iter()))
    {
        *dst = p - r1 - r2 + a;
    }
}

#[must_use]
#[inline]
fn score_acc(acc_w: &[i16; HIDDEN], acc_b: &[i16; HIDDEN]) -> (i32, i32) {
    #[allow(clippy::cast_possible_truncation)]
    const QA_I16: i16 = QA as i16;
    let mut sum_w = 0i32;
    let mut sum_b = 0i32;
    for ((&aw, &ab), &w2) in acc_w.iter().zip(acc_b.iter()).zip(W2.0.iter()) {
        let vw = i32::from(aw.clamp(0, QA_I16));
        let vb = i32::from(ab.clamp(0, QA_I16));
        let w2i = i32::from(w2);
        sum_w += vw * vw * w2i;
        sum_b += vb * vb * w2i;
    }
    #[allow(clippy::cast_possible_truncation)]
    let nn_w = ((i64::from(sum_w) * 400) / DIVISOR) as i32;
    #[allow(clippy::cast_possible_truncation)]
    let nn_b = ((i64::from(sum_b) * 400) / DIVISOR) as i32;
    (nn_w, nn_b)
}

/// Lazy ply-indexed incremental NNUE accumulator stack for search.
#[derive(Debug)]
pub struct AccStack {
    entries: Vec<AccEntry>,
}

impl Default for AccStack {
    fn default() -> Self {
        Self::new()
    }
}

impl AccStack {
    /// Allocates an uninitialized accumulator stack sized for maximum search ply.
    #[must_use]
    pub fn new() -> Self {
        Self {
            entries: vec![AccEntry::ZERO; MAX_ACC_PLY],
        }
    }

    /// Refreshes ply 0 accumulators from `board`.
    #[inline]
    pub fn reset(&mut self, board: &Board) {
        let root = &mut self.entries[0];
        root.w = B1.0;
        root.b = B1.0;
        let mut occ = board.occupied();
        while let Some(sq) = occ.pop_lsb() {
            if let Some(piece) = board.piece_at(sq) {
                let (fw, fb) = feat_pair(piece, sq);
                let rw = &W1.0[usize::from(fw)];
                let rb = &W1.0[usize::from(fb)];
                for ((aw, ab), (&ww, &wb)) in root
                    .w
                    .iter_mut()
                    .zip(root.b.iter_mut())
                    .zip(rw.iter().zip(rb.iter()))
                {
                    *aw += ww;
                    *ab += wb;
                }
            }
        }
        root.kind = AccKind::Computed;
    }

    /// Records a lazy move delta at `child_ply` using `board_before` prior to `make_move`.
    #[inline]
    pub fn push_move(&mut self, child_ply: usize, board_before: &Board, mv: Move) {
        let Some(entry) = self.entries.get_mut(child_ply) else {
            return;
        };
        let Some(moved) = board_before.piece_at(mv.from()) else {
            return;
        };
        let placed = mv
            .promotion()
            .map_or(moved, |pt| Piece::new(moved.color, pt));
        entry.rem1 = feat_pair(moved, mv.from());
        entry.add = feat_pair(placed, mv.to());
        if let Some(cap) = board_before.piece_at(mv.to()) {
            entry.rem2 = feat_pair(cap, mv.to());
            entry.kind = AccKind::Capture;
        } else {
            entry.kind = AccKind::Quiet;
        }
    }

    /// Records a null move pass-through at `child_ply`.
    #[inline]
    pub fn push_null(&mut self, child_ply: usize) {
        if let Some(entry) = self.entries.get_mut(child_ply) {
            entry.kind = AccKind::Null;
        }
    }

    /// Lazily synchronizes accumulators up to `ply` and returns symmetric residual scores.
    #[must_use]
    #[inline]
    pub fn evaluate_residual(&mut self, board: &Board, ply: usize) -> (i32, i32) {
        if ply >= self.entries.len() {
            return evaluate_nnue_residual(board);
        }
        if !matches!(self.entries[0].kind, AccKind::Computed) {
            self.reset(board);
            return score_acc(&self.entries[0].w, &self.entries[0].b);
        }
        let mut base = ply;
        while base > 0 && !matches!(self.entries[base].kind, AccKind::Computed) {
            base -= 1;
        }
        for p in (base + 1)..=ply {
            let (left, right) = self.entries.split_at_mut(p);
            let prev = &left[p - 1];
            let cur = &mut right[0];
            match cur.kind {
                AccKind::Computed => {}
                AccKind::Null => {
                    cur.w = prev.w;
                    cur.b = prev.b;
                }
                AccKind::Quiet => {
                    apply_quiet(
                        &prev.w,
                        &mut cur.w,
                        &W1.0[usize::from(cur.rem1.0)],
                        &W1.0[usize::from(cur.add.0)],
                    );
                    apply_quiet(
                        &prev.b,
                        &mut cur.b,
                        &W1.0[usize::from(cur.rem1.1)],
                        &W1.0[usize::from(cur.add.1)],
                    );
                }
                AccKind::Capture => {
                    apply_capture(
                        &prev.w,
                        &mut cur.w,
                        &W1.0[usize::from(cur.rem1.0)],
                        &W1.0[usize::from(cur.rem2.0)],
                        &W1.0[usize::from(cur.add.0)],
                    );
                    apply_capture(
                        &prev.b,
                        &mut cur.b,
                        &W1.0[usize::from(cur.rem1.1)],
                        &W1.0[usize::from(cur.rem2.1)],
                        &W1.0[usize::from(cur.add.1)],
                    );
                }
            }
            cur.kind = AccKind::Computed;
        }
        score_acc(&self.entries[ply].w, &self.entries[ply].b)
    }
}

/// Evaluates symmetric 300 -> 64 `SCReLU` NNUE residual scores `(white_cp, black_cp)`.
#[must_use]
#[inline]
pub fn evaluate_nnue_residual(board: &Board) -> (i32, i32) {
    let mut acc_w = AlignedHidden(B1.0);
    let mut acc_b = AlignedHidden(B1.0);
    for color in [Color::White, Color::Black] {
        let is_white = color == Color::White;
        let base_w = usize::from(!is_white) * 150;
        let base_b = usize::from(is_white) * 150;
        for pt in PIECE_TYPES {
            let mut bb = board.pieces_bb(color, pt);
            let pt_off = pt.index() * 25;
            while let Some(sq) = bb.pop_lsb() {
                let sq_i = sq.index();
                let rw = &W1.0[base_w + pt_off + sq_i];
                let rb = &W1.0[base_b + pt_off + FLIP_SQ[sq_i]];
                for ((aw, ab), (ww, wb)) in acc_w
                    .0
                    .iter_mut()
                    .zip(acc_b.0.iter_mut())
                    .zip(rw.iter().zip(rb.iter()))
                {
                    *aw += *ww;
                    *ab += *wb;
                }
            }
        }
    }

    score_acc(&acc_w.0, &acc_b.0)
}
